import { randomUUID } from "node:crypto";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";

const EMPTY = { books: [] };

export function createStore(filePath) {
  async function ensureFile() {
    await mkdir(dirname(filePath), { recursive: true });
    try {
      await readFile(filePath, "utf8");
    } catch (error) {
      if (error && error.code === "ENOENT") {
        await writeFile(filePath, JSON.stringify(EMPTY, null, 2) + "\n", "utf8");
        return;
      }
      throw error;
    }
  }

  async function read() {
    await ensureFile();
    const raw = await readFile(filePath, "utf8");
    const parsed = raw.trim() ? JSON.parse(raw) : EMPTY;
    if (!parsed || !Array.isArray(parsed.books)) {
      throw new Error("books file is missing a books array");
    }
    return parsed;
  }

  async function write(data) {
    await ensureFile();
    await writeFile(filePath, JSON.stringify(data, null, 2) + "\n", "utf8");
  }

  return {
    filePath,

    async list() {
      const data = await read();
      return data.books;
    },

    async get(id) {
      const data = await read();
      return data.books.find((book) => book.id === id) ?? null;
    },

    async add({ title, author, notes }) {
      const cleanTitle = String(title ?? "").trim();
      const cleanAuthor = String(author ?? "").trim();
      const cleanNotes = String(notes ?? "").trim();
      if (!cleanTitle) {
        throw new Error("Title is required");
      }
      if (!cleanAuthor) {
        throw new Error("Author is required");
      }

      const book = {
        id: randomUUID(),
        title: cleanTitle,
        author: cleanAuthor,
        notes: cleanNotes,
        status: "reading",
        createdAt: new Date().toISOString(),
        finishedAt: null,
      };

      const data = await read();
      data.books.push(book);
      await write(data);
      return book;
    },

    async finish(id) {
      const data = await read();
      const book = data.books.find((item) => item.id === id);
      if (!book) return null;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await write(data);
      }
      return book;
    },
  };
}

