export function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

export function layout({ title, body }) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    :root { color-scheme: light; }
    body { font-family: Georgia, "Times New Roman", serif; margin: 0; background: #f6f1e7; color: #1f1a14; }
    main { max-width: 42rem; margin: 0 auto; padding: 2rem 1.25rem 4rem; }
    h1, h2 { font-weight: 600; letter-spacing: -0.02em; }
    h1 { font-size: 2rem; margin: 0 0 0.25rem; }
    h2 { font-size: 1.15rem; margin: 2rem 0 0.75rem; }
    p.lede { margin: 0 0 1.5rem; color: #5c5146; }
    a { color: #7a3e12; }
    ul { list-style: none; padding: 0; margin: 0; }
    li { background: #fffdf8; border: 1px solid #e4d8c4; border-radius: 8px; padding: 0.85rem 1rem; margin: 0 0 0.6rem; }
    li a.book-link { font-size: 1.05rem; text-decoration: none; }
    li a.book-link:hover { text-decoration: underline; }
    .author { color: #5c5146; margin: 0.2rem 0 0; }
    form.add, form.inline { margin: 0; }
    form.add { background: #fffdf8; border: 1px solid #e4d8c4; border-radius: 8px; padding: 1rem; display: grid; gap: 0.75rem; }
    label { display: grid; gap: 0.3rem; font-size: 0.95rem; }
    input, textarea { font: inherit; padding: 0.45rem 0.55rem; border: 1px solid #cbbba3; border-radius: 6px; background: #fff; }
    textarea { min-height: 6rem; resize: vertical; }
    button, .button { font: inherit; background: #7a3e12; color: #fffdf8; border: 0; border-radius: 6px; padding: 0.45rem 0.8rem; cursor: pointer; text-decoration: none; display: inline-block; }
    button.secondary { background: transparent; color: #7a3e12; border: 1px solid #cbbba3; }
    .row { display: flex; justify-content: space-between; gap: 1rem; align-items: center; }
    .notes { white-space: pre-wrap; background: #fffdf8; border: 1px solid #e4d8c4; border-radius: 8px; padding: 1rem; }
    .empty { color: #5c5146; font-style: italic; }
    .error { background: #fde8e4; border: 1px solid #e7b2a8; color: #7a2418; padding: 0.7rem 0.85rem; border-radius: 8px; }
    nav { margin: 1.25rem 0 0; }
  </style>
</head>
<body>
  <main>
    ${body}
  </main>
</body>
</html>`;
}

function bookItem(book) {
  const finished = book.status === "finished";
  const action = finished
    ? ""
    : `<form class="inline" method="post" action="/books/${encodeURIComponent(book.id)}/finish">
        <button type="submit">Mark finished</button>
      </form>`;
  return `<li>
    <div class="row">
      <div>
        <a class="book-link" href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
        <p class="author">${escapeHtml(book.author)}</p>
      </div>
      ${action}
    </div>
  </li>`;
}

function bookList(books, emptyText) {
  if (!books.length) return `<p class="empty">${escapeHtml(emptyText)}</p>`;
  return `<ul>${books.map(bookItem).join("")}</ul>`;
}

export function homePage({ reading, finished, error, form }) {
  const values = {
    title: form?.title ?? "",
    author: form?.author ?? "",
    notes: form?.notes ?? "",
  };
  const errorBlock = error ? `<p class="error">${escapeHtml(error)}</p>` : "";
  return layout({
    title: "Books",
    body: `<h1>Books</h1>
      <p class="lede">What you're reading, and what you've finished.</p>
      ${errorBlock}
      <h2>Currently reading</h2>
      ${bookList(reading, "Nothing in progress.")}
      <h2>Finished</h2>
      ${bookList(finished, "No finished books yet.")}
      <h2>Add a book</h2>
      <form class="add" method="post" action="/books">
        <label>Title
          <input name="title" required value="${escapeHtml(values.title)}">
        </label>
        <label>Author
          <input name="author" required value="${escapeHtml(values.author)}">
        </label>
        <label>Notes
          <textarea name="notes">${escapeHtml(values.notes)}</textarea>
        </label>
        <button type="submit">Add book</button>
      </form>`,
  });
}

export function bookPage(book) {
  const finished = book.status === "finished";
  const status = finished ? "Finished" : "Currently reading";
  const action = finished
    ? `<p class="author">${escapeHtml(status)}</p>`
    : `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
        <button type="submit">Mark finished</button>
      </form>`;
  const notes = book.notes?.trim()
    ? `<div class="notes">${escapeHtml(book.notes)}</div>`
    : `<p class="empty">No notes yet.</p>`;
  return layout({
    title: book.title,
    body: `<h1>${escapeHtml(book.title)}</h1>
      <p class="author">${escapeHtml(book.author)}</p>
      <p class="author">${escapeHtml(status)}</p>
      ${action}
      <h2>Notes</h2>
      ${notes}
      <nav><a href="/">Back to all books</a></nav>`,
  });
}

export function notFoundPage() {
  return layout({
    title: "Not found",
    body: `<h1>Book not found</h1>
      <p class="lede">That link doesn't match a book on this shelf.</p>
      <nav><a href="/">Back to all books</a></nav>`,
  });
}

