import { mkdtemp, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { createStore } from "./store.js";
import { startServer } from "./server.js";

async function tempFile() {
  const dir = await mkdtemp(join(tmpdir(), "books-"));
  return join(dir, "books.json");
}

describe("store", () => {
  it("adds a reading book and persists it to JSON", async () => {
    const filePath = await tempFile();
    const store = createStore(filePath);
    const book = await store.add({
      title: "  The Left Hand of Darkness  ",
      author: "Ursula K. Le Guin",
      notes: "Winter.",
    });

    expect(book.status).toBe("reading");
    expect(book.title).toBe("The Left Hand of Darkness");
    expect(book.finishedAt).toBeNull();

    const raw = JSON.parse(await readFile(filePath, "utf8"));
    expect(raw.books).toHaveLength(1);
    expect(raw.books[0].id).toBe(book.id);

    const reopened = createStore(filePath);
    expect(await reopened.get(book.id)).toMatchObject({
      title: "The Left Hand of Darkness",
      author: "Ursula K. Le Guin",
      notes: "Winter.",
      status: "reading",
    });
  });

  it("marks a book finished and keeps it after a new store is opened", async () => {
    const filePath = await tempFile();
    const store = createStore(filePath);
    const book = await store.add({ title: "Kindred", author: "Octavia Butler" });
    const finished = await store.finish(book.id);
    expect(finished.status).toBe("finished");
    expect(finished.finishedAt).toEqual(expect.any(String));

    const again = createStore(filePath);
    const books = await again.list();
    expect(books.filter((item) => item.status === "finished")).toHaveLength(1);
    expect(books.filter((item) => item.status === "reading")).toHaveLength(0);
  });

  it("rejects a book without a title", async () => {
    const store = createStore(await tempFile());
    await expect(store.add({ title: "  ", author: "Someone" })).rejects.toThrow(/title/i);
  });
});

describe("http", () => {
  const servers = [];
  afterEach(async () => {
    await Promise.all(servers.splice(0).map((server) => new Promise((resolve) => server.close(resolve))));
  });

  async function boot() {
    const started = await startServer({ filePath: await tempFile() });
    servers.push(started.server);
    return started;
  }

  it("shows reading and finished books, then a shareable book page", async () => {
    const { url, store } = await boot();
    const reading = await store.add({ title: "Piranesi", author: "Susanna Clarke", notes: "Halls." });
    const done = await store.add({ title: "Circe", author: "Madeline Miller" });
    await store.finish(done.id);

    const home = await fetch(url);
    expect(home.status).toBe(200);
    const html = await home.text();
    expect(html).toContain("Currently reading");
    expect(html).toContain("Finished");
    expect(html).toContain("Piranesi");
    expect(html).toContain("Circe");
    expect(html).toContain(`/books/${reading.id}`);

    const page = await fetch(`${url}/books/${reading.id}`);
    expect(page.status).toBe(200);
    const detail = await page.text();
    expect(detail).toContain("Piranesi");
    expect(detail).toContain("Susanna Clarke");
    expect(detail).toContain("Halls.");
  });

  it("adds a book from the form and marks it finished", async () => {
    const { url } = await boot();
    const created = await fetch(`${url}/books`, {
      method: "POST",
      headers: { "content-type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ title: "Dune", author: "Frank Herbert", notes: "Spice." }),
      redirect: "manual",
    });
    expect(created.status).toBe(303);
    const location = created.headers.get("location");
    expect(location).toMatch(/^\/books\/.+/);

    const finished = await fetch(`${url}${location}/finish`, { method: "POST", redirect: "manual" });
    expect(finished.status).toBe(303);

    const page = await fetch(`${url}${location}`);
    const html = await page.text();
    expect(html).toContain("Dune");
    expect(html).toContain("Finished");
    expect(html).toContain("Spice.");
  });
});

