import { randomUUID } from "node:crypto";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";

const EMPTY = { books: [] };

export function createStore(filePath) {
  async function ensureFile() {
    await mkdir(dirname(filePath), { recursive: true });
    try {
      await readFile(filePath, "utf8");
    } catch (error) {
      if (error && error.code === "ENOENT") {
        await writeFile(filePath, JSON.stringify(EMPTY, null, 2) + "\n", "utf8");
        return;
      }
      throw error;
    }
  }

  async function read() {
    await ensureFile();
    const raw = await readFile(filePath, "utf8");
    const parsed = raw.trim() ? JSON.parse(raw) : EMPTY;
    if (!parsed || !Array.isArray(parsed.books)) {
      throw new Error("books file is missing a books array");
    }
    return parsed;
  }

  async function write(data) {
    await ensureFile();
    await writeFile(filePath, JSON.stringify(data, null, 2) + "\n", "utf8");
  }

  return {
    filePath,

    async list() {
      const data = await read();
      return data.books;
    },

    async get(id) {
      const data = await read();
      return data.books.find((book) => book.id === id) ?? null;
    },

    async add({ title, author, notes }) {
      const cleanTitle = String(title ?? "").trim();
      const cleanAuthor = String(author ?? "").trim();
      const cleanNotes = String(notes ?? "").trim();
      if (!cleanTitle) {
        throw new Error("Title is required");
      }
      if (!cleanAuthor) {
        throw new Error("Author is required");
      }

      const book = {
        id: randomUUID(),
        title: cleanTitle,
        author: cleanAuthor,
        notes: cleanNotes,
        status: "reading",
        createdAt: new Date().toISOString(),
        finishedAt: null,
      };

      const data = await read();
      data.books.push(book);
      await write(data);
      return book;
    },

    async finish(id) {
      const data = await read();
      const book = data.books.find((item) => item.id === id);
      if (!book) return null;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await write(data);
      }
      return book;
    },
  };
}

export function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

export function layout({ title, body }) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    :root { color-scheme: light; }
    body { font-family: Georgia, "Times New Roman", serif; margin: 0; background: #f6f1e7; color: #1f1a14; }
    main { max-width: 42rem; margin: 0 auto; padding: 2rem 1.25rem 4rem; }
    h1, h2 { font-weight: 600; letter-spacing: -0.02em; }
    h1 { font-size: 2rem; margin: 0 0 0.25rem; }
    h2 { font-size: 1.15rem; margin: 2rem 0 0.75rem; }
    p.lede { margin: 0 0 1.5rem; color: #5c5146; }
    a { color: #7a3e12; }
    ul { list-style: none; padding: 0; margin: 0; }
    li { background: #fffdf8; border: 1px solid #e4d8c4; border-radius: 8px; padding: 0.85rem 1rem; margin: 0 0 0.6rem; }
    li a.book-link { font-size: 1.05rem; text-decoration: none; }
    li a.book-link:hover { text-decoration: underline; }
    .author { color: #5c5146; margin: 0.2rem 0 0; }
    form.add, form.inline { margin: 0; }
    form.add { background: #fffdf8; border: 1px solid #e4d8c4; border-radius: 8px; padding: 1rem; display: grid; gap: 0.75rem; }
    label { display: grid; gap: 0.3rem; font-size: 0.95rem; }
    input, textarea { font: inherit; padding: 0.45rem 0.55rem; border: 1px solid #cbbba3; border-radius: 6px; background: #fff; }
    textarea { min-height: 6rem; resize: vertical; }
    button, .button { font: inherit; background: #7a3e12; color: #fffdf8; border: 0; border-radius: 6px; padding: 0.45rem 0.8rem; cursor: pointer; text-decoration: none; display: inline-block; }
    button.secondary { background: transparent; color: #7a3e12; border: 1px solid #cbbba3; }
    .row { display: flex; justify-content: space-between; gap: 1rem; align-items: center; }
    .notes { white-space: pre-wrap; background: #fffdf8; border: 1px solid #e4d8c4; border-radius: 8px; padding: 1rem; }
    .empty { color: #5c5146; font-style: italic; }
