  </style>
</head>
<body>
  <main>
    ${body}
  </main>
</body>
</html>`;
}

function bookItem(book) {
  const finished = book.status === "finished";
  const action = finished
    ? ""
    : `<form class="inline" method="post" action="/books/${encodeURIComponent(book.id)}/finish">
        <button type="submit">Mark finished</button>
      </form>`;
  return `<li>
    <div class="row">
      <div>
        <a class="book-link" href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
        <p class="author">${escapeHtml(book.author)}</p>
      </div>
      ${action}
    </div>
  </li>`;
}

function bookList(books, emptyText) {
  if (!books.length) return `<p class="empty">${escapeHtml(emptyText)}</p>`;
  return `<ul>${books.map(bookItem).join("")}</ul>`;
}

export function homePage({ reading, finished, error, form }) {
  const values = {
    title: form?.title ?? "",
    author: form?.author ?? "",
    notes: form?.notes ?? "",
  };
  const errorBlock = error ? `<p class="error">${escapeHtml(error)}</p>` : "";
  return layout({
    title: "Books",
    body: `<h1>Books</h1>
      <p class="lede">What you're reading, and what you've finished.</p>
      ${errorBlock}
      <h2>Currently reading</h2>
      ${bookList(reading, "Nothing in progress.")}
      <h2>Finished</h2>
      ${bookList(finished, "No finished books yet.")}
      <h2>Add a book</h2>
      <form class="add" method="post" action="/books">
        <label>Title
          <input name="title" required value="${escapeHtml(values.title)}">
        </label>
        <label>Author
          <input name="author" required value="${escapeHtml(values.author)}">
        </label>
        <label>Notes
          <textarea name="notes">${escapeHtml(values.notes)}</textarea>
        </label>
        <button type="submit">Add book</button>
      </form>`,
  });
}

export function bookPage(book) {
  const finished = book.status === "finished";
  const status = finished ? "Finished" : "Currently reading";
  const action = finished
    ? `<p class="author">${escapeHtml(status)}</p>`
    : `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
        <button type="submit">Mark finished</button>
      </form>`;
  const notes = book.notes?.trim()
    ? `<div class="notes">${escapeHtml(book.notes)}</div>`
    : `<p class="empty">No notes yet.</p>`;
  return layout({
    title: book.title,
    body: `<h1>${escapeHtml(book.title)}</h1>
      <p class="author">${escapeHtml(book.author)}</p>
      <p class="author">${escapeHtml(status)}</p>
      ${action}
      <h2>Notes</h2>
      ${notes}
      <nav><a href="/">Back to all books</a></nav>`,
  });
}

export function notFoundPage() {
  return layout({
    title: "Not found",
    body: `<h1>Book not found</h1>
      <p class="lede">That link doesn't match a book on this shelf.</p>
      <nav><a href="/">Back to all books</a></nav>`,
  });
}

import { createServer } from "node:http";
import { createStore } from "./store.js";
import { bookPage, homePage, notFoundPage } from "./html.js";

const MAX_BODY = 64 * 1024;

function send(res, status, html) {
  res.writeHead(status, {
    "content-type": "text/html; charset=utf-8",
    "cache-control": "no-store",
  });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY) {
        reject(Object.assign(new Error("Body too large"), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf8");
      resolve(new URLSearchParams(raw));
    });
    req.on("error", reject);
  });
}

export function createApp(store) {
  return async function app(req, res) {
    const url = new URL(req.url || "/", "http://localhost");
    const path = url.pathname;
    const method = req.method || "GET";

    try {
      if (method === "GET" && path === "/") {
        const books = await store.list();
        send(res, 200, homePage({
          reading: books.filter((book) => book.status !== "finished"),
          finished: books.filter((book) => book.status === "finished"),
        }));
        return;
      }

      if (method === "POST" && path === "/books") {
        const body = await readBody(req);
        const form = {
          title: body.get("title") ?? "",
          author: body.get("author") ?? "",
          notes: body.get("notes") ?? "",
        };
        try {
          const book = await store.add(form);
          redirect(res, `/books/${encodeURIComponent(book.id)}`);
        } catch (error) {
          const books = await store.list();
          send(res, 400, homePage({
            reading: books.filter((book) => book.status !== "finished"),
            finished: books.filter((book) => book.status === "finished"),
            error: error.message,
            form,
          }));
        }
        return;
      }

      const bookMatch = path.match(/^\/books\/([^/]+)$/);
      if (method === "GET" && bookMatch) {
        const book = await store.get(decodeURIComponent(bookMatch[1]));
        if (!book) {
          send(res, 404, notFoundPage());
          return;
        }
        send(res, 200, bookPage(book));
        return;
      }

      const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
      if (method === "POST" && finishMatch) {
        const id = decodeURIComponent(finishMatch[1]);
        const book = await store.finish(id);
        if (!book) {
          send(res, 404, notFoundPage());
          return;
        }
        redirect(res, `/books/${encodeURIComponent(book.id)}`);
        return;
      }

      send(res, 404, notFoundPage());
    } catch (error) {
      const status = error.status || 500;
      send(res, status, `<!DOCTYPE html><html><body><h1>Something went wrong</h1><p>${status}</p></body></html>`);
    }
  };
}

export function startServer({ filePath, port = 0, host = "127.0.0.1" } = {}) {
  const store = createStore(filePath);
  const server = createServer(createApp(store));
  return new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(port, host, () => {
      const address = server.address();
      resolve({
        server,
        store,
        port: address.port,
        url: `http://${host}:${address.port}`,
      });
    });
  });
}

